import{_ as d,o,c as n,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/COUNT.md","filePath":"manual-zh/COUNT.md","lastUpdated":1785684581000}'),r={name:"manual-zh/COUNT.md"};function e(a,t,p,i,l,c){return o(),n("div",null,[...t[0]||(t[0]=[s(`<h3 id="_12-4-count" tabindex="-1">12.4 COUNT <a class="header-anchor" href="#_12-4-count" aria-label="Permalink to &quot;12.4 COUNT&quot;">​</a></h3><pre><code>COUNT var_name = var… (value…)
    [/var_name = var… (value…)]…

Each value takes one of the following forms:
        number
        string
        num1 THRU num2
        MISSING
        SYSMIS
where num1 is a numeric expression or the words LO  or LOWEST
      and num2 is a numeric expression  or HI or HIGHEST.
</code></pre><p><code>COUNT</code> 创建或替换一个数值 <em>target</em>（目标）变量，用于统计每个个案在一个或多个 <em>test</em>（检验）变量中某个 <em>criterion</em>（判定）值或一组判定的出现次数。</p><p>目标变量的值始终为非负整数。它们永远不会缺失。目标变量被赋予 F8.2 输出格式。参见 <a href="./Input-and-Output-Formats">Input and Output Formats</a>。任何变量，包括字符串变量，都可以作为检验变量。</p><p>检验变量的用户缺失值与其他任何值一视同仁。它们<strong>不会</strong>被当作系统缺失值。作为判定值或落在判定值范围内的用户缺失值，会像其他值一样被计数。不过（对于数值变量），关键字 <code>MISSING</code> 可用于指代所有系统缺失值和用户缺失值。</p><p><code>COUNT</code> 目标变量按指定顺序赋值。在命令 <code>COUNT A=A B(1) /B=A B(2).</code> 中，发生以下动作：</p><ul><li>统计 A 与 B 之间 1 出现的次数。</li><li>A 被赋为该值。</li><li>统计 B 与 A 的<strong>新</strong>值之间 1 出现的次数。</li><li>B 被赋为该值。</li></ul><p>尽管如此，所有 <code>COUNT</code> 判定变量必须在过程执行之前就已存在——它们不能是该命令前面作为目标变量创建的！请将此类命令拆分为两个独立的命令。</p><h4 id="_12-4-1-计数示例" tabindex="-1">12.4.1 计数示例 <a class="header-anchor" href="#_12-4-1-计数示例" aria-label="Permalink to &quot;12.4.1 计数示例&quot;">​</a></h4><p>在数据集 hotel.sav 的调查结果中，一位经理想知道有多少受访者对问题 <strong>v1</strong>、<strong>v2</strong> 和 <strong>v3</strong> 给出了较低值的回答。这可以通过示例 12.4 中的代码找到。具体而言，该代码创建一个新变量，并用 <strong>v1</strong>–<strong>v2</strong> 中取值为 2 或更低的值的个数填充它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&quot;hotel.sav&quot;.  count low_counts = v1 v2 v3 (low thru 2).  list /variables v1 v2 v3 low_counts.</span></span></code></pre></div><p><strong>示例 12.4：</strong> 统计 <strong>v1</strong>、<strong>v2</strong> 和 <strong>v3</strong> 的低值回答</p><p>在示例 12.4 中，<code>COUNT</code> 转换创建了一个新变量 <strong>low_counts</strong>，并使用 <code>LIST</code> 命令显示其值。</p><p>如果使用图形用户界面，必须采用两步过程来设置 <code>COUNT</code> 转换。第一个对话框（截图 12.3）用于选择变量。然后，必须单击标有“Define Values...”（定义值）的按钮，以打开用于选择要计数的取值的对话框。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 12.3：</strong> 已选择变量 <strong>v1</strong>、<strong>v2</strong> 和 <strong>v3</strong>，准备定义要计数的值</p><p>在此对话框中，必须选择要计数的值——本例中为不超过且包含 2 的所有值——如截图 12.4 所示，然后单击“Add”（添加）。可以添加任意多个范围。添加完所有所需范围后，单击“Continue”（继续）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>截图 12.4：</strong> 计数“Define Values”对话框，已选择 ‘lowest thru 2’</p><p>在结果 12.2 中，我们可以看到 <code>COUNT</code> 转换完成后 <strong>low_counts</strong> 的值。第一个值为 1，因为在 <strong>v1</strong>、<strong>v2</strong> 和 <strong>v3</strong> 中只有一个变量取值为 2 或更低。第二个值为 2，因为 <strong>v1</strong> 和 <strong>v2</strong> 的取值都为 2 或更低。</p><table tabindex="0"><thead><tr><th>v1</th><th>v2</th><th>v3</th><th>low_counts</th></tr></thead><tbody><tr><td>4</td><td>2</td><td>3</td><td>1.00</td></tr><tr><td>1</td><td>1</td><td>4</td><td>2.00</td></tr><tr><td>4</td><td>2</td><td>2</td><td>2.00</td></tr><tr><td>3</td><td>1</td><td>3</td><td>1.00</td></tr><tr><td>5</td><td>3</td><td>1</td><td>1.00</td></tr><tr><td>2</td><td>2</td><td>5</td><td>2.00</td></tr><tr><td>3</td><td>2</td><td>4</td><td>1.00</td></tr><tr><td>1</td><td>4</td><td>5</td><td>1.00</td></tr><tr><td>3</td><td>2</td><td>3</td><td>1.00</td></tr><tr><td>2</td><td>5</td><td>4</td><td>1.00</td></tr><tr><td>4</td><td>2</td><td>2</td><td>2.00</td></tr><tr><td>2</td><td>1</td><td>4</td><td>2.00</td></tr><tr><td>1</td><td>2</td><td>5</td><td>2.00</td></tr><tr><td>2</td><td>3</td><td>3</td><td>1.00</td></tr><tr><td>4</td><td>1</td><td>1</td><td>2.00</td></tr><tr><td>1</td><td>1</td><td>5</td><td>2.00</td></tr><tr><td>1</td><td>5</td><td>5</td><td>1.00</td></tr></tbody></table><p><strong>结果 12.2：</strong> <code>COUNT</code> 转换运行后 <strong>v1</strong>、<strong>v2</strong>、<strong>v3</strong> 和 <strong>low_counts</strong> 的值</p>`,22)])])}const h=d(r,[["render",e]]);export{u as __pageData,h as default};
